const PREFIX = 'boids-';
const CACHE = PREFIX + VERSION;

/** @param {string} path */
const absolute = (path) => new URL(path, self.location.href).href;
/** The app shell: what the start URL and in-app navigations show. */
const SHELL = absolute('./index.html');
/** The scope root, i.e. the start URL without its query string. */
const ROOT_PATH = new URL('./', self.location.href).pathname;
/** Absolute URL → expected hash. */
const HASHES = new Map(Object.entries(FILES).map(([path, hash]) => [absolute(path), hash]));

/** @param {ArrayBuffer} buffer */
async function sha256(buffer) {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
  let binary = '';
  for (const byte of digest) binary += String.fromCharCode(byte);
  return btoa(binary);
}

/**
 * Store a response in the cache if its content matches the expected hash.
 * Only the content type is kept: the body is already decoded.
 * @param {Cache} cache
 * @param {string} url
 * @param {Response} response
 * @param {string} hash
 * @returns {Promise<boolean>} Whether it was stored.
 */
async function storeVerified(cache, url, response, hash) {
  if (!response.ok) return false;
  const body = await response.arrayBuffer();
  if ((await sha256(body)) !== hash) return false;
  const type = response.headers.get('Content-Type');
  await cache.put(url, new Response(body, { headers: type ? { 'Content-Type': type } : {} }));
  return true;
}

/**
 * Save every file of this version, or fail. Files that did verify are kept
 * even when another one fails, so a retry only downloads what is missing.
 */
async function saveVersion() {
  const cache = await caches.open(CACHE);
  const results = await Promise.allSettled(
    [...HASHES].map(async ([url, hash]) => {
      // Already saved (and verified) by an earlier, interrupted attempt.
      if (await cache.match(url)) return;
      const response = await fetch(url, { cache: 'reload' });
      if (!(await storeVerified(cache, url, response, hash))) {
        throw new Error(`${url} (HTTP ${response.status}) does not match version ${VERSION}`);
      }
    }),
  );
  const failure = results.find((result) => result.status === 'rejected');
  if (failure) throw failure.reason;
}

self.addEventListener('install', (event) => {
  event.waitUntil(saveVersion());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(respond(event, request, url));
});

/**
 * @param {FetchEvent} event
 * @param {Request} request
 * @param {URL} url
 * @returns {Promise<Response>}
 */
async function respond(event, request, url) {
  // The start URL (with or without query parameters) is the app shell.
  const key = url.pathname === ROOT_PATH ? SHELL : url.origin + url.pathname;
  const cache = await caches.open(CACHE);
  const saved = await cache.match(key);
  if (saved) return saved;
  const hash = HASHES.get(key);
  try {
    const response = await fetch(request);
    // A file of the app missing from the saved copy (storage partly
    // cleared?): put it back if it is the right version.
    if (hash) event.waitUntil(storeVerified(cache, key, response.clone(), hash).catch(() => false));
    return response;
  } catch (error) {
    if (request.mode === 'navigate') {
      const shell = await cache.match(SHELL);
      if (shell) return shell;
    }
    throw error;
  }
}

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'SKIP_WAITING') self.skipWaiting();
  else if (type === 'STATUS' && event.ports[0]) {
    event.ports[0].postMessage({ version: VERSION, files: HASHES.size });
  }
});
